// Assembles the three things the First Paper Kit promises on the landing page:
// the scoping worksheet, the LaTeX submission kit, and the vetted venue shortlist.
//
// The shortlist is generated by scripts/build_kit_shortlist.mjs from the same venue index
// the free checker queries, so a paying student gets evidence and source URLs rather than
// a list of names somebody typed out.

import { worksheet } from './worksheet.mjs';
import { latexKit } from './latex.mjs';
import { shortlist, builtAt } from './shortlist.mjs';

export function buildKit() {
  return {
    version: '1.0',
    shortlistBuiltAt: builtAt,
    worksheet,
    latex: latexKit,
    venues: {
      groups: shortlist,
      total: shortlist.reduce((n, g) => n + g.venues.length, 0),
      // Said plainly inside the paid product, not just on the free page.
      method:
        'Every venue here returned INDEXED from the Benchless venue index, which is built ' +
        'from DOAJ, the Scopus source list, OpenAlex/IEEE and the public predatory lists. ' +
        'The evidence and source URL are shown so you can check each one yourself. The fit ' +
        'notes and the difficulty rating are my judgement, not a database result, and they ' +
        'are worth exactly what one person\'s opinion is worth.',
      caveat:
        'An INDEXED verdict means the venue exists in an indexing record. It is not advice ' +
        'to submit, and it is not a statement about review quality. Indexing status also ' +
        'changes — re-check before you submit, not just before you start.'
    }
  };
}

export default buildKit;
